window.geoPointInRing = function(pt, ring){
  const x=pt[0], y=pt[1]; let inside=false;
  for(let i=0, j=ring.length-1; i<ring.length; j=i++){
    const xi=ring[i][0], yi=ring[i][1], xj=ring[j][0], yj=ring[j][1];
    if(((yi>y)!==(yj>y)) && (x < (xj-xi)*(y-yi)/(yj-yi)+xi)) inside=!inside;
  }
  return inside;
};
window.geoFind = function(layer, lat, lng){
  if(lat==null||lng==null||isNaN(lat)||isNaN(lng)||!layer) return null;
  for(const f of layer){ for(const ring of f.rings){ if(window.geoPointInRing([lat,lng], ring)) return f; } }
  return null;
};
window.findParroquiaGeo = (lat,lng) => { const f=window.geoFind(window.PARROQUIAS_GEO,lat,lng); return f?f.name:null; };
window.findComunidad    = (lat,lng) => { const f=window.geoFind(window.COMUNIDADES_GEO,lat,lng); return f?f.name:null; };
window.findSueloUrbano  = (lat,lng) => { const f=window.geoFind(window.SUELO_URBANO_GEO,lat,lng); return f?f.name:null; };
